contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from does a transfer to to of amount. We call transfer from this contract by first
    // ensuring this contract has the requested balance via mintToken (onlyOwner required).
    // Since the checker deploys a fresh C with owner = this contract, this contract is owner and
    // may mint/burn/freeze. We use that to set up balances and frozen flags.
    function run(address from, address to, uint256 amount, bool freezeFrom, bool freezeTo) public payable {
        require(from != address(0) && to != address(0));

        // Ensure this test contract is owner (constructor of C set owner to deployer which is this contract)
        // Mint some tokens to `from` and `to` to allow transfer attempts. Use amounts large enough.
        uint256 mintForFrom = amount + 1;
        uint256 mintForTo = 1;
        c.mintToken(from, mintForFrom);
        c.mintToken(to, mintForTo);

        // record totalSupply and per-account balances before the transfer attempt
        uint256 totalBefore = c.totalSupply();
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);

        // possibly freeze accounts
        c.freezeAccount(from, freezeFrom);
        c.freezeAccount(to, freezeTo);

        // Try to have `from` transfer to `to`. But transfer is msg.sender based, and our contract is
        // the caller; to simulate `from` as sender, we instead call _transfer via C.transfer isn't usable
        // for arbitrary sender. However the contract exposes only transfer(msg.sender...). The checker
        // environment sets msg.sender for calls to c as this contract. So we instead check the general
        // property for transfers made by this contract (i.e., msg.sender == this contract). Thus we
        // mint to this contract if needed and perform transfer to `to`. To still involve `from` we
        // assert rule only when `from` equals address(this) OR when from equals to; to keep a general
        // non-trivial property we will perform the transfer from address(this) to `to` and then assert
        // the invariant for those two accounts (sender and recipient).

        // For clarity, set sender = address(this)
        address sender = address(this);
        // ensure sender has balance
        c.mintToken(sender, amount + 1);
        uint256 senderBefore = c.balanceOf(sender);
        uint256 recipientBefore = c.balanceOf(to);
        uint256 totalBefore2 = c.totalSupply();

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 senderAfter = c.balanceOf(sender);
        uint256 recipientAfter = c.balanceOf(to);
        uint256 totalAfter = c.totalSupply();

        // General rule: If the transfer call did NOT revert, then totalSupply is unchanged and
        // sender+recipient balances are preserved (sum before == sum after), and neither account is frozen.
        // If the call reverted, no guarantees required by this property (except we still reached the assert).
        assert(
            reverted || (
                totalAfter == totalBefore2 &&
                senderBefore + recipientBefore == senderAfter + recipientAfter &&
                c.frozenAccount(sender) == false &&
                c.frozenAccount(to) == false
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that successful transfers do not change totalSupply.
    // Params: recipient `to` must be non-zero and amount within minted balance.
    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        // Ensure this test contract (the owner) has enough balance to cover the transfer.
        // Mint exactly amount tokens to this contract if needed.
        // To avoid overflow in mint, require amount is not ridiculously large (but allow any uint256).
        c.mintToken(address(this), amount);

        uint256 totalBefore = c.totalSupply();
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 totalAfter = c.totalSupply();

        // Assert: if the transfer succeeded (did not revert), totalSupply must remain equal.
        assert(reverted || totalAfter == totalBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function; caller is this contract (deployer of c)
    function run(uint256 burnAmount) public payable {
        require(true);
        // Read before-values
        address self = address(this);
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(self);

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(self);

        // If the call did not revert, it must have reduced totalSupply and caller balance by exactly burnAmount
        // If it reverted, no change is required. This captures the owner-only requirement because only owner can burn.
        assert(reverted || (afterTotal + burnAmount == beforeTotal && afterBalance + burnAmount == beforeBalance));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call freezeAccount as this contract (msg.sender = this test contract)
    // Parameters: target address to freeze/unfreeze, and the boolean freeze value.
    function run(address target, bool freeze) public payable {
        require(true);
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // After the call, either it reverted (so no state change is guaranteed),
        // or it succeeded and the public getter frozenAccount(target) must equal freeze.
        bool getterEquals = c.frozenAccount(target) == freeze;
        // The general rule: if the call did not revert then the frozenAccount getter reflects the argument.
        assert(reverted || getterEquals);
    }

    receive() external payable {}
}
